import {specification,compatibilityErrors,normalize} from './vehicle-specs.js';
const popular=['Toyota','Ford','Nissan','Suzuki','Kia','Hyundai','Chevrolet','Volkswagen','Honda','Mazda','Mitsubishi','Jeep','BMW','Mercedes-Benz','Audi','Subaru','Changan','GWM','Haval','BYD','Geely','JAC','Renault','Peugeot','Fiat','Citroën','Volvo','Lexus','Dodge','RAM','Isuzu','MG','Chery','Jetour','Foton'];
export function initVehicleAssistant({form,api,node,onChange}){
 const fields=['make','year','name','version','engine','fuel','transmission','drive','type'],options=new Map(),menus=new Map();let generation=0,active=null,trims=[],timer,modelsKey='',trimsKey='',lastIdentity={},manual=false,makesLoaded=false;
 const ref=node('input');ref.type='hidden';ref.name='catalogRef';form.append(ref);
 const status=document.querySelector('#spec-status'),sources=document.querySelector('#spec-source'),errors=document.querySelector('#spec-errors');
 const retry=node('button','catalog-retry','Actualizar listas');retry.type='button';retry.onclick=()=>refreshRemote(true);sources.after(retry);
 for(const key of fields){const input=form.elements[key];input.removeAttribute('list');input.setAttribute('aria-label',input.closest('label').firstChild.textContent.trim());const wrap=node('div','vehicle-choice'),trigger=node('button','choice-trigger','⌄'),menu=node('div','choice-menu');trigger.type='button';trigger.addEventListener('pointerdown',e=>e.preventDefault());trigger.setAttribute('aria-label','Mostrar opciones de '+input.closest('label').firstChild.textContent);menu.id='choices-'+key;menu.hidden=true;menu.setAttribute('role','listbox');input.parentNode.insertBefore(wrap,input);wrap.append(input,trigger,menu);input.setAttribute('role','combobox');input.setAttribute('aria-autocomplete','list');input.setAttribute('aria-controls',menu.id);input.setAttribute('aria-expanded','false');menus.set(key,{input,menu});
 function close(){menu.hidden=true;input.setAttribute('aria-expanded','false');}function show(){for(const [other,v]of menus)if(other!==key){v.menu.hidden=true;v.input.setAttribute('aria-expanded','false');}draw(key,true);if(key==='make'&&!makesLoaded)loadMakes();if(['name','version'].includes(key))refreshRemote();}
 trigger.onclick=()=>menu.hidden?show():close();input.addEventListener('focus',show);input.addEventListener('input',()=>{draw(key);if(['make','year','name'].includes(key)){clearTimeout(timer);timer=setTimeout(()=>refreshRemote(),450);}});input.addEventListener('keydown',e=>{if(e.key==='Escape')close();if(e.key==='ArrowDown'){e.preventDefault();show();menu.querySelector('button')?.focus();}});menu.addEventListener('keydown',e=>{const buttons=[...menu.querySelectorAll('button')],i=buttons.indexOf(document.activeElement);if(e.key==='ArrowDown'){e.preventDefault();buttons[(i+1)%buttons.length]?.focus();}if(e.key==='ArrowUp'){e.preventDefault();buttons[(i-1+buttons.length)%buttons.length]?.focus();}if(e.key==='Escape'){close();input.focus();}});wrap.addEventListener('focusout',()=>queueMicrotask(()=>{if(!wrap.contains(document.activeElement))close();}));
 }
 function set(key,items){options.set(key,items.map(v=>typeof v==='string'?{value:v,label:v}:v));draw(key);}
 function draw(key,all=false){const {input,menu}=menus.get(key),list=options.get(key)||[],q=normalize(input.value);const filtered=all?list:list.filter(o=>normalize(o.label).includes(q)||normalize(o.value).includes(q));menu.replaceChildren();if(!filtered.length)menu.append(node('p','',menu.dataset.loading==='true'?'Consultando el catálogo…':list.length?'No coincide ninguna opción. Puedes revisar el texto.':'Sin opciones verificadas para esta combinación.'));for(const item of filtered){const b=node('button','',item.label);b.type='button';b.setAttribute('role','option');b.addEventListener('pointerdown',e=>e.preventDefault());b.setAttribute('aria-selected',String(input.value===item.value));b.onclick=async()=>{input.value=item.value;menu.hidden=true;input.setAttribute('aria-expanded','false');if(key==='version'&&item.id){await selectTrim(item.id);return;}input.dispatchEvent(new Event('input',{bubbles:true}));input.dispatchEvent(new Event('change',{bubbles:true}));};menu.append(b);}if(all){menu.hidden=false;input.setAttribute('aria-expanded','true');}}
 set('make',popular);set('year',Array.from({length:new Date().getFullYear()+2-1900},(_,i)=>String(new Date().getFullYear()+1-i)));for(const k of ['name','version','engine','fuel','transmission','drive','type'])set(k,[]);
 const specOptions=(spec,key)=>key==='drive'?(spec?.drive?[spec.drive]:[]):spec?.[key]||[];
 function data(){return Object.fromEntries(new FormData(form));}
 function localSpec(v){return specification(v)||((normalize(v.make)==='ford'&&normalize(v.name)==='bronco'&&v.year==='2026')?specification({...v,version:'Badlands'}):null);}
 function paint(){const v=data(),spec=active||(!ref.value?localSpec(v):null);if(!active){for(const key of ['engine','fuel','transmission','drive','type'])set(key,specOptions(spec,key));if(!trims.length)set('version',spec?.versions||[]);}else for(const key of ['engine','fuel','transmission','drive','type'])set(key,specOptions(spec,key));
 for(const key of ['engine','fuel','transmission','drive','type']){form.elements[key].readOnly=!!active||!!ref.value;form.elements[key].placeholder=active?'Elige una opción':manual?'Según ficha de la unidad':'Selecciona primero la versión';}
 if(spec){status.textContent=spec.market;sources.replaceChildren();const a=node('a','','Consultar fuente de la configuración ↗');a.href=spec.source;a.target='_blank';a.rel='noopener noreferrer';sources.append(a);}else{sources.replaceChildren();status.textContent=manual?'Modo manual: completa con la ficha de la unidad. No se certifican datos que el catálogo no devuelve.':'Elige marca → año → modelo → versión. Las listas consultan fuentes externas gratuitas; no se mezclan motores de versiones distintas.';}
 const invalid=active?['engine','fuel','transmission','drive','type'].filter(k=>v[k]&&!specOptions(active,k).some(x=>normalize(x)===normalize(v[k]))).map(k=>'Revisa '+k+': no corresponde a la configuración elegida.'):ref.value?[]:compatibilityErrors(v);errors.textContent=invalid.join(' ');return invalid;}
 async function loadMakes(){try{const r=await api('admin/catalog','POST',{stage:'makes'});set('make',[...new Map([...popular,...r.options].map(v=>[normalize(v),v])).values()].sort((a,b)=>a.localeCompare(b,'es')));makesLoaded=!!r.options.length;}catch{status.textContent='No se pudo consultar la lista completa de marcas. Las marcas frecuentes siguen disponibles.';}}
 async function refreshRemote(force=false){const v=data(),ticket=++generation,mk=[v.make,v.year].join('|'),tk=[v.make,v.year,v.name].join('|');paint();if(!v.make)return;
 try{if(force||modelsKey!==mk){menus.get('name').menu.dataset.loading='true';draw('name');status.textContent='Buscando modelos de '+v.make+(v.year?' · '+v.year:'')+'…';const r=await api('admin/catalog','POST',{stage:'models',...v});if(ticket!==generation)return;modelsKey=mk;menus.get('name').menu.dataset.loading='false';set('name',r.options);status.textContent=r.notice;}
 if(v.name&&/^\d{4}$/.test(v.year)&&(force||trimsKey!==tk)){menus.get('version').menu.dataset.loading='true';draw('version');status.textContent='Buscando versiones exactas de '+v.make+' '+v.name+' '+v.year+'…';const r=await api('admin/catalog','POST',{stage:'trims',...v});if(ticket!==generation)return;trimsKey=tk;menus.get('version').menu.dataset.loading='false';trims=r.options||[];if(trims.length)set('version',trims);else paint();status.textContent=r.notice;}
 }catch(e){if(ticket===generation){menus.get('name').menu.dataset.loading='false';menus.get('version').menu.dataset.loading='false';status.textContent=e.message+' Puedes reintentar o completar con la documentación de la unidad.';}}}
 async function selectTrim(id){const v=data(),ticket=++generation;status.textContent='Cargando el motor y la transmisión de esta versión…';try{const r=await api('admin/catalog','POST',{stage:'detail',id,...v});if(ticket!==generation)return;active=r.spec;manual=false;ref.value=active.ref||'carapi:'+active.id;form.elements.version.value=active.version;for(const k of ['engine','fuel','transmission','drive','type'])form.elements[k].value=specOptions(active,k).length===1?specOptions(active,k)[0]:'';paint();onChange();}catch(e){status.textContent=e.message;}}
 for(const key of ['make','year','name'])form.elements[key].addEventListener('change',()=>{const v=data();if(lastIdentity[key]!==v[key]){generation++;active=null;ref.value='';trims=[];trimsKey='';if(key==='make'){form.elements.name.value='';set('name',[]);modelsKey='';}for(const k of ['version','engine','fuel','transmission','drive','type'])form.elements[k].value='';manual=false;lastIdentity=data();paint();refreshRemote();onChange();}});
 form.elements.version.addEventListener('change',()=>{if(active&&normalize(active.version)!==normalize(form.elements.version.value)){active=null;ref.value='';for(const k of ['engine','fuel','transmission','drive','type'])form.elements[k].value='';}paint();onChange();});
 const manualButton=node('button','catalog-manual','Completar con la ficha de mi vehículo');manualButton.type='button';manualButton.onclick=()=>{generation++;active=null;ref.value='';manual=true;paint();};retry.after(manualButton);
 const vinBox=node('details','vin-assistant');vinBox.innerHTML='<summary>¿Tienes el VIN? Consultar los datos de la unidad</summary><p>Esta consulta envía el VIN al servicio público NHTSA/vPIC. No se guarda el VIN en la publicación. Su cobertura depende del fabricante y del mercado.</p><label>VIN (17 caracteres)<input id="lookup-vin" maxlength="17" autocomplete="off"></label><button type="button" id="decode-vin">Consultar VIN</button>';manualButton.after(vinBox);vinBox.querySelector('button').onclick=async()=>{try{const r=await api('admin/catalog','POST',{stage:'vin',vin:vinBox.querySelector('input').value,year:form.elements.year.value});active=null;ref.value='';for(const [key,val]of Object.entries(r.vehicle))if(val)form.elements[key].value=val;lastIdentity=data();trimsKey='';manual=true;paint();status.textContent=r.notice;onChange();refreshRemote();}catch(e){status.textContent=e.message;}};
 return{validate:paint,open(v){generation++;active=null;trims=[];manual=false;modelsKey='';trimsKey='';ref.value=v?.catalogRef||'';lastIdentity=data();paint();if(ref.value)selectTrim(ref.value.startsWith('carapi:')?ref.value.slice(7):ref.value).then(()=>refreshRemote());else refreshRemote();},refresh:refreshRemote};
}
